<?php
require_once __DIR__ . '/inc/config.php';
require_once __DIR__ . '/inc/auth.php';
require_admin();
$orders = read_orders();
$grandTotal = array_reduce($orders, fn($sum, $order) => $sum + (float)($order['price'] ?? 0), 0);
?>
