<?php require_once __DIR__.'/inc/config.php'; require_once __DIR__.'/inc/auth.php'; require_admin(); $orders=read_orders(); $total=array_reduce($orders,fn($s,$o)=>$s+(float)($o['price']??0),0); ?><!doctype html><html><head><meta charset="utf-8"><title>Restaurant Bill</title><style>body{font:16px Arial;padding:30px}.bill{max-width:700px;margin:auto}.bill h1{color:#e85d04}table{width:100%;border-collapse:collapse}td,th{padding:10px;border-bottom:1px solid #ddd;text-align:left}</style></head><body><div class="bill"><h1>Studio Table by Sam</h1><h2>All Orders Bill</h2><table><tr><th>Order</th><th>Customer</th><th>Items</th><th>Total</th></tr><?php foreach($orders as $o):?><tr><td><?=e($o['orderId']??'')?></td><td><?=e($o['customer']??'')?></td><td><?=e($o['name']??'')?></td><td>Rs <?=number_format((float)($o['price']??0),2)?></td></tr><?php endforeach;?></table><h2>Grand total: Rs <?=number_format($total,2)?></h2><button onclick="print()">Print</button></div></body></html>
